mapper.select:
SELECT id, ledger_id, account_id, category_id, type, amount, occurred_at, note, created_at, updated_at
FROM transactions
WHERE id = #{id}

SELECT id, ledger_id, account_id, category_id, type, amount, occurred_at, note, created_at, updated_at
FROM transactions
WHERE ledger_id IN

    #{ledgerId}

AND occurred_at >= #{start}
AND occurred_at < #{end}

    AND type = #{type}


    AND category_id = #{categoryId}


    AND account_id = #{accountId}


    AND note LIKE CONCAT('%', #{keyword}, '%')

ORDER BY occurred_at DESC, id DESC

SELECT COUNT(*)
FROM transactions
WHERE category_id = #{categoryId}

SELECT COUNT(*)
FROM transactions
WHERE account_id = #{accountId}
